<?php require 'config.php'; $msg='';$buyers=$pdo->query('SELECT buyer_id,name FROM buyers ORDER BY name')->fetchAll();$produce=$pdo->query('SELECT produce_id,name FROM produce ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $bid=(int)($_POST['buyer_id']??0);$pid=(int)($_POST['produce_id']??0);$qty=(float)($_POST['quantity']??0);if($bid&&$pid&&$qty>0){$pdo->prepare('INSERT INTO orders(buyer_id,produce_id,quantity,status,order_date) VALUES(?,?,?,"Pending",CURDATE())')->execute([$bid,$pid,$qty]);$msg='Order recorded as Pending. Stock is checked before dispatch.';}}
$rows=$pdo->query('SELECT o.order_id,b.name buyer,p.name produce,o.quantity,o.status,o.order_date FROM orders o JOIN buyers b ON o.buyer_id=b.buyer_id JOIN produce p ON o.produce_id=p.produce_id ORDER BY o.order_id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><title>Orders</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Buyer Orders</h1><nav><a href="index.php">Dashboard</a><a href="farmers.php">Farmers</a><a href="deliveries.php">Deliveries</a><a href="dispatches.php">Dispatches</a><a href="reports.php">Reports</a></nav></header><main><h2>Record Order</h2><?=htmlspecialchars($msg)?><form method="post"><label>Buyer<select name="buyer_id" required><option value="">Choose buyer</option><?php foreach($buyers as $b):?><option value="<?=$b['buyer_id']?>"><?=htmlspecialchars($b['name'])?></option><?php endforeach;?></select></label><label>Produce<select name="produce_id" required><option value="">Choose produce</option><?php foreach($produce as $p):?><option value="<?=$p['produce_id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label><label>Quantity (kg)<input type="number" name="quantity" min=".01" step=".01" required></label><button>Save Order</button></form><h2>Orders</h2><table><tr><th>ID</th><th>Buyer</th><th>Produce</th><th>Quantity</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['order_id']?></td><td><?=htmlspecialchars($r['buyer'])?></td><td><?=htmlspecialchars($r['produce'])?></td><td><?=$r['quantity']?></td><td><?=$r['status']?></td><td><?=$r['order_date']?></td></tr><?php endforeach;?></table></main></body></html>
